mapper.select:
SELECT id, process_instance_id, node_id, node_name, assignee, status, priority, variables, create_time, complete_time, complete_user, comment FROM wf_task WHERE assignee = #{assignee}
AND status = #{status}
ORDER BY create_time DESC

SELECT t.id, t.process_instance_id, t.node_id, t.node_name, t.assignee, t.status, t.priority, t.variables, t.create_time, t.complete_time, t.complete_user, t.comment FROM wf_task t LEFT JOIN wf_process_instance pi ON t.process_instance_id = pi.id WHERE t.assignee = #{assignee}
AND t.status = #{status}
AND pi.app_id = #{appId} ORDER BY t.create_time DESC

SELECT t.id, t.process_instance_id, t.node_id, t.node_name, t.assignee, t.status, t.priority, t.variables, t.create_time, t.complete_time, t.complete_user, t.comment FROM wf_task t LEFT JOIN wf_process_instance pi ON t.process_instance_id = pi.id WHERE t.assignee = #{assignee}
AND t.status = #{status}
AND pi.app_id IS NULL ORDER BY t.create_time DESC
